# Batch: recompute from scratch over a bounded partition.
# Rerun is safe: same input -> same output.
def batch_hourly_avg(events):
    # events: all records for hour H, already complete (or complete enough)
    by_hour = {}
    for e in events:
        s = by_hour.setdefault(e.hour, [0, 0])  # [sum, count]
        s[0] += e.amount
        s[1] += 1
    # atomic overwrite downstream; late data fixed by next rerun
    return {h: total / cnt for h, (total, cnt) in by_hour.items()}
